173.         {
174.             switch (value)
175.             {
176.                 case null:
177.                     writer.WriteNullValue();
178.                     break;
179.                 case IJsonModel<T> jsonModel:
180.                     jsonModel.Write(writer, options ?? WireOptions);
181.                     break;
182.                 case IUtf8JsonSerializable serializable:
183.                     serializable.Write(writer);
184.                     break;
185.                 case byte[] bytes:
186.                     writer.WriteBase64StringValue(bytes);
187.                     break;
188.                 case BinaryData bytes0:
189.                     writer.WriteBase64StringValue(bytes0);
190.                     break;
191.                 case JsonElement json:
192.                     json.WriteTo(writer);
193.                     break;
194.                 case int i:
195.                     writer.WriteNumberValue(i);
196.                     break;
197.                 case decimal d:
198.                     writer.WriteNumberValue(d);
199.                     break;
200.                 case double d0:
201.                     if (double.IsNaN(d0))
202.                     {
203.                         writer.WriteStringValue("NaN");
204.                     }
205.                     else
206.                     {
207.                         writer.WriteNumberValue(d0);
208.                     }
209.                     break;
210.                 case float f:
211.                     writer.WriteNumberValue(f);
212.                     break;
213.                 case long l:
214.                     writer.WriteNumberValue(l);
215.                     break;
216.                 case string s:
217.                     writer.WriteStringValue(s);
218.                     break;
219.                 case bool b:
220.                     writer.WriteBooleanValue(b);
221.                     break;
222.                 case Guid g:
223.                     writer.WriteStringValue(g);
224.                     break;
225.                 case DateTimeOffset dateTimeOffset:
226.                     writer.WriteStringValue(dateTimeOffset, "O");
227.                     break;
228.                 case DateTime dateTime:
